func truncate(s string, n int) string {
    return s[:n]
}

func main() {
    fmt.Printf("%q\n", truncate("Phở", 3))
}

s := "Phở"
for i := range s {
    fmt.Printf("%c", s[i])
}

func reverse(s string) string {
    b := []byte(s)
    for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
        b[i], b[j] = b[j], b[i]
    }
    return string(b)
}
